[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>CommerceForge Dev Docs</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&family=JetBrains+Mono:wght@400;500&display=swap" rel="stylesheet">
<style>
  *,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
  :root{
    --bg:#0d1117;
    --bg2:#161b22;
    --bg3:#21262d;
    --border:rgba(255,255,255,0.08);
    --border-hover:rgba(255,255,255,0.18);
    --text:#e6edf3;
    --muted:#8b949e;
    --accent:#00d4aa;
    --accent2:#475F91;
    --accent-glow:rgba(0,212,170,0.15);
    --radius:12px;
    --font:-apple-system,"Inter",system-ui,sans-serif;
    --mono:"JetBrains Mono",monospace;
  }
  html{scroll-behavior:smooth}
  body{background:var(--bg);color:var(--text);font-family:var(--font);line-height:1.6;-webkit-font-smoothing:antialiased}

  /* NAV */
  nav{position:sticky;top:0;z-index:100;background:rgba(13,17,23,0.85);backdrop-filter:blur(12px);border-bottom:1px solid var(--border);padding:0 2rem}
  .nav-inner{max-width:1280px;margin:0 auto;display:flex;align-items:center;height:60px;gap:0}
  .nav-logo{font-weight:700;font-size:1.05rem;color:var(--text);text-decoration:none;margin-right:2rem;display:flex;align-items:center;gap:0.5rem;flex-shrink:0}
  .nav-logo-icon{width:28px;height:28px;background:linear-gradient(135deg,var(--accent),var(--accent2));border-radius:6px;display:flex;align-items:center;justify-content:center;font-size:0.75rem;font-weight:800;color:#0d1117}
  .nav-links{display:flex;align-items:center;gap:0.25rem;flex:1}
  .nav-links a{color:var(--muted);text-decoration:none;padding:0.4rem 0.75rem;border-radius:6px;font-size:0.875rem;transition:color 0.15s,background 0.15s}
  .nav-links a:hover{color:var(--text);background:var(--bg3)}
  .nav-links a.active{color:var(--text)}
  .nav-right{display:flex;align-items:center;gap:0.75rem}
  .nav-search{display:flex;align-items:center;gap:0.5rem;background:var(--bg3);border:1px solid var(--border);border-radius:8px;padding:0.375rem 0.75rem;font-size:0.8rem;color:var(--muted);cursor:pointer;transition:border-color 0.15s}
  .nav-search:hover{border-color:var(--border-hover)}
  .nav-search kbd{background:var(--bg2);border:1px solid var(--border);border-radius:4px;padding:0.1rem 0.35rem;font-size:0.7rem;font-family:var(--mono)}
  .nav-login{background:var(--bg3);border:1px solid var(--border);color:var(--text);padding:0.375rem 1rem;border-radius:8px;font-size:0.875rem;cursor:pointer;transition:border-color 0.15s,background 0.15s;text-decoration:none}
  .nav-login:hover{background:var(--bg2);border-color:var(--border-hover)}

  /* HERO */
  .hero{padding:5rem 2rem 4rem;text-align:center;position:relative;overflow:hidden}
  .hero::before{content:'';position:absolute;top:-50%;left:50%;transform:translateX(-50%);width:800px;height:600px;background:radial-gradient(ellipse,rgba(0,212,170,0.08) 0%,transparent 70%);pointer-events:none}
  .hero-tag{display:inline-flex;align-items:center;gap:0.4rem;background:rgba(0,212,170,0.1);border:1px solid rgba(0,212,170,0.25);color:var(--accent);padding:0.3rem 0.85rem;border-radius:100px;font-size:0.78rem;font-weight:500;margin-bottom:1.5rem;letter-spacing:0.02em}
  .hero-tag-dot{width:6px;height:6px;background:var(--accent);border-radius:50%;animation:pulse 2s ease-in-out infinite}
  @keyframes pulse{0%,100%{opacity:1}50%{opacity:0.4}}
  .hero h1{font-size:clamp(2.2rem,5vw,3.8rem);font-weight:700;letter-spacing:-0.02em;line-height:1.15;margin-bottom:1.25rem;background:linear-gradient(160deg,#e6edf3 0%,#8b949e 100%);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text}
  .hero p{font-size:1.1rem;color:var(--muted);max-width:680px;margin:0 auto 2.5rem;line-height:1.7}
  .hero-ctas{display:flex;flex-wrap:wrap;gap:0.75rem;justify-content:center}
  .btn-primary{background:var(--accent);color:#0d1117;padding:0.65rem 1.4rem;border-radius:8px;font-size:0.9rem;font-weight:600;text-decoration:none;transition:all 0.15s;border:none;cursor:pointer;white-space:nowrap}
  .btn-primary:hover{background:#00f0c0;transform:translateY(-1px);box-shadow:0 4px 20px rgba(0,212,170,0.35)}
  .btn-secondary{background:transparent;color:var(--text);padding:0.65rem 1.4rem;border-radius:8px;font-size:0.9rem;font-weight:500;text-decoration:none;border:1px solid var(--border);transition:all 0.15s;cursor:pointer;white-space:nowrap}
  .btn-secondary:hover{border-color:var(--border-hover);background:var(--bg3);transform:translateY(-1px)}

  /* SECTIONS */
  section{padding:4rem 2rem}
  .section-inner{max-width:1280px;margin:0 auto}
  .section-header{margin-bottom:2.5rem}
  .section-label{font-size:0.75rem;font-weight:600;letter-spacing:0.08em;text-transform:uppercase;color:var(--accent);margin-bottom:0.5rem}
  .section-title{font-size:1.75rem;font-weight:700;letter-spacing:-0.02em;margin-bottom:0.5rem}
  .section-sub{color:var(--muted);font-size:1rem;max-width:600px}

  /* PRODUCT CARDS */
  .cards-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:1.25rem}
  .card{background:var(--bg2);border:1px solid var(--border);border-radius:var(--radius);padding:2rem;transition:all 0.2s;position:relative;overflow:hidden}
  .card::before{content:'';position:absolute;inset:0;background:var(--accent-glow);opacity:0;transition:opacity 0.2s}
  .card:hover{border-color:rgba(0,212,170,0.3);transform:translateY(-2px);box-shadow:0 8px 40px rgba(0,0,0,0.4)}
  .card:hover::before{opacity:1}
  .card-icon{width:48px;height:48px;border-radius:10px;display:flex;align-items:center;justify-content:center;font-size:1.4rem;margin-bottom:1.25rem;position:relative}
  .card-icon-apps{background:rgba(71,95,145,0.2);border:1px solid rgba(71,95,145,0.4)}
  .card-icon-storefronts{background:rgba(0,212,170,0.15);border:1px solid rgba(0,212,170,0.3)}
  .card-icon-agents{background:rgba(147,51,234,0.2);border:1px solid rgba(147,51,234,0.4)}
  .card h3{font-size:1.2rem;font-weight:600;margin-bottom:0.6rem}
  .card p{color:var(--muted);font-size:0.9rem;line-height:1.6;margin-bottom:1.5rem}
  .card-link{color:var(--accent);text-decoration:none;font-size:0.875rem;font-weight:500;display:inline-flex;align-items:center;gap:0.35rem;transition:gap 0.15s}
  .card-link:hover{gap:0.55rem}

  /* CLI SETUP */
  .cli-section{background:var(--bg2);border-top:1px solid var(--border);border-bottom:1px solid var(--border)}
  .cli-layout{display:grid;grid-template-columns:1fr 1fr;gap:4rem;align-items:start}
  @media(max-width:900px){.cli-layout{grid-template-columns:1fr}}
  .cli-left h2{font-size:1.75rem;font-weight:700;letter-spacing:-0.02em;margin-bottom:0.75rem}
  .cli-left p{color:var(--muted);font-size:0.95rem;line-height:1.7}

  /* ACCORDION */
  .accordion{margin-top:1.5rem;display:flex;flex-direction:column;gap:0.5rem}
  .acc-item{border:1px solid var(--border);border-radius:10px;overflow:hidden;transition:border-color 0.2s}
  .acc-item.open{border-color:rgba(0,212,170,0.3)}
  .acc-trigger{width:100%;background:var(--bg3);border:none;padding:1rem 1.25rem;display:flex;align-items:center;justify-content:space-between;cursor:pointer;color:var(--text);font-size:0.925rem;font-weight:500;font-family:var(--font);transition:background 0.15s}
  .acc-trigger:hover{background:#2d333b}
  .acc-item.open .acc-trigger{background:rgba(0,212,170,0.08);color:var(--accent)}
  .acc-chevron{transition:transform 0.25s;color:var(--muted);font-size:0.8rem}
  .acc-item.open .acc-chevron{transform:rotate(180deg)}
  .acc-body{max-height:0;overflow:hidden;transition:max-height 0.35s ease}
  .acc-item.open .acc-body{max-height:600px}
  .acc-content{padding:1.25rem;border-top:1px solid var(--border)}
  .steps{display:flex;flex-direction:column;gap:0.75rem;margin-bottom:1rem}
  .step{display:flex;gap:0.75rem;align-items:flex-start;font-size:0.875rem;color:var(--muted)}
  .step-num{width:22px;height:22px;background:rgba(0,212,170,0.15);border:1px solid rgba(0,212,170,0.3);border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:0.7rem;font-weight:600;color:var(--accent);flex-shrink:0;margin-top:1px}

  /* CODE BLOCK */
  .code-block{background:#0d1117;border:1px solid var(--border);border-radius:10px;overflow:hidden;margin-top:1rem}
  .code-tabs{display:flex;border-bottom:1px solid var(--border);background:var(--bg3)}
  .code-tab{padding:0.5rem 1rem;font-size:0.8rem;font-weight:500;cursor:pointer;border:none;background:none;color:var(--muted);transition:color 0.15s,background 0.15s;font-family:var(--font);border-bottom:2px solid transparent;margin-bottom:-1px}
  .code-tab.active{color:var(--accent);border-bottom-color:var(--accent);background:var(--bg2)}
  .code-content{position:relative}
  .code-pane{display:none;padding:1.25rem 1.5rem}
  .code-pane.active{display:block}
  pre{font-family:var(--mono);font-size:0.82rem;line-height:1.65;color:#e6edf3;overflow-x:auto}
  .kw{color:#ff7b72}
  .str{color:#a5d6ff}
  .cm{color:#8b949e;font-style:italic}
  .fn{color:#d2a8ff}
  .copy-btn{position:absolute;top:0.75rem;right:0.75rem;background:var(--bg3);border:1px solid var(--border);color:var(--muted);padding:0.25rem 0.6rem;border-radius:6px;font-size:0.75rem;cursor:pointer;font-family:var(--font);transition:all 0.15s}
  .copy-btn:hover{color:var(--text);border-color:var(--border-hover)}

  /* LAUNCH CTA */
  .launch-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:1.25rem}
  .launch-card{background:linear-gradient(135deg,var(--bg2),var(--bg3));border:1px solid var(--border);border-radius:var(--radius);padding:2rem;transition:all 0.2s}
  .launch-card:hover{border-color:var(--border-hover);transform:translateY(-2px)}
  .launch-badge{display:inline-block;background:rgba(71,95,145,0.2);border:1px solid rgba(71,95,145,0.4);color:#7aa2f7;padding:0.2rem 0.6rem;border-radius:4px;font-size:0.72rem;font-weight:600;letter-spacing:0.05em;text-transform:uppercase;margin-bottom:1rem}
  .launch-card h3{font-size:1.15rem;font-weight:600;margin-bottom:0.6rem}
  .launch-card p{color:var(--muted);font-size:0.875rem;line-height:1.6;margin-bottom:1.25rem}

  /* COMMUNITY */
  .community-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:1rem}
  .comm-card{background:var(--bg2);border:1px solid var(--border);border-radius:10px;padding:1.5rem;transition:all 0.2s;text-decoration:none;color:var(--text);display:flex;align-items:center;gap:1rem}
  .comm-card:hover{border-color:var(--border-hover);background:var(--bg3);transform:translateY(-1px)}
  .comm-icon{width:40px;height:40px;border-radius:8px;display:flex;align-items:center;justify-content:center;font-size:1.2rem;flex-shrink:0}
  .comm-card h4{font-size:0.9rem;font-weight:600;margin-bottom:0.2rem}
  .comm-card p{font-size:0.8rem;color:var(--muted)}

  /* FOOTER */
  footer{background:var(--bg2);border-top:1px solid var(--border);padding:3rem 2rem 2rem}
  .footer-inner{max-width:1280px;margin:0 auto}
  .footer-logo{font-weight:700;font-size:1rem;margin-bottom:2rem;display:flex;align-items:center;gap:0.5rem}
  .footer-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:2rem;margin-bottom:2.5rem}
  .footer-col h5{font-size:0.78rem;font-weight:600;letter-spacing:0.08em;text-transform:uppercase;color:var(--muted);margin-bottom:0.75rem}
  .footer-col a{display:block;color:var(--muted);text-decoration:none;font-size:0.85rem;padding:0.2rem 0;transition:color 0.15s}
  .footer-col a:hover{color:var(--text)}
  .footer-bottom{border-top:1px solid var(--border);padding-top:1.5rem;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:1rem}
  .footer-bottom p{font-size:0.8rem;color:var(--muted)}

  /* MOBILE */
  @media(max-width:768px){
    .nav-links{display:none}
    .hero{padding:3rem 1.5rem 2.5rem}
    section{padding:3rem 1.5rem}
    .hero-ctas{flex-direction:column;align-items:center}
    .cards-grid{grid-template-columns:1fr}
    .community-grid{grid-template-columns:1fr 1fr}
    .footer-grid{grid-template-columns:1fr 1fr}
  }
  @media(max-width:480px){
    .community-grid{grid-template-columns:1fr}
    .footer-grid{grid-template-columns:1fr}
  }
</style>
</head>
