<section class="hero">
  <div class="hero-tag">
    <span class="hero-tag-dot"></span>
    Developer Documentation
  </div>
  <h1>CommerceForge<br>Dev Docs</h1>
  <p>Learn how to build an app, or customize your storefront. Whether you're just getting started, deep in the development process, or ready to distribute and monetize your work, CommerceForge's docs, dev tools and frameworks make building easy and efficient.</p>
  <div class="hero-ctas">
    <a href="apps-build.html" class="btn-primary">Build your first app →</a>
    <a href="storefronts.html" class="btn-secondary">Build a storefront →</a>
    <a href="agents.html" class="btn-secondary">Build agents with UCP →</a>
  </div>
</section>

<!-- PRODUCT CARDS -->
<section>
  <div class="section-inner">
    <div class="section-header">
      <div class="section-label">Product Areas</div>
      <h2 class="section-title">Build anything on CommerceForge</h2>
      <p class="section-sub">Three powerful product areas to extend, customize, and automate commerce experiences.</p>
    </div>
    <div class="cards-grid">
      <div class="card">
        <div class="card-icon card-icon-apps">🧩</div>
        <h3>Apps</h3>
        <p>Extend CommerceForge's core functionality with apps that integrate into the admin, online store, checkout and more.</p>
        <a href="apps-build.html" class="card-link">Build your first app →</a>
      </div>
      <div class="card">
        <div class="card-icon card-icon-storefronts">🛍️</div>
        <h3>Storefronts</h3>
        <p>Help merchants express their unique brand by building a custom theme or Hydrogen storefront with full creative control.</p>
        <a href="storefronts.html" class="card-link">Build a storefront →</a>
      </div>
      <div class="card">
        <div class="card-icon card-icon-agents">🤖</div>
        <h3>Agents</h3>
        <p>Build agentic shopping experiences powered by CommerceForge merchants, from product discovery to checkout.</p>
        <a href="agents.html" class="card-link">Build agents with UCP →</a>
      </div>
    </div>
  </div>
</section>

<!-- CLI SETUP -->
<section class="cli-section">
  <div class="section-inner">
    <div class="cli-layout">
      <div class="cli-left">
        <div class="section-label">CLI 3.0</div>
        <h2>Accelerate development with CommerceForge CLI 3.0</h2>
        <p>Initialize new apps, themes, and headless storefronts in an instant with the latest CommerceForge CLI. A single command installs all the dependencies you need, including the CLI itself, so you can dive straight into development.</p>
        <div class="accordion" id="cli-accordion">
          <div class="acc-item open" data-type="apps">
            <button class="acc-trigger" onclick="toggleAcc(this)">
              <span>Apps</span>
              <span class="acc-chevron">▼</span>
            </button>
            <div class="acc-body">
              <div class="acc-content">
                <div class="steps">
                  <div class="step"><div class="step-num">1</div><span>Install CommerceForge CLI globally.</span></div>
                  <div class="step"><div class="step-num">2</div><span>Navigate to the directory where you want to create your app.</span></div>
                  <div class="step"><div class="step-num">3</div><span>Run the second command to create a new app. Your app will be added as a new subdirectory.</span></div>
                </div>
                <div class="init-cmd">
                  <div class="code-block">
                    <div class="code-content">
                      <div class="code-pane active">
                        <pre><span class="fn">$</span> <span class="str">commerceforge app init</span></pre>
                      </div>
                      <button class="copy-btn" onclick="copyCode(this,'commerceforge app init')">Copy</button>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
          <div class="acc-item" data-type="themes">
            <button class="acc-trigger" onclick="toggleAcc(this)">
              <span>Themes</span>
              <span class="acc-chevron">▼</span>
            </button>
            <div class="acc-body">
              <div class="acc-content">
                <div class="steps">
                  <div class="step"><div class="step-num">1</div><span>Install CommerceForge CLI globally.</span></div>
                  <div class="step"><div class="step-num">2</div><span>Navigate to the directory where you want to create your theme.</span></div>
                  <div class="step"><div class="step-num">3</div><span>Run the second command to clone a starter theme. Your theme will be created in a new subdirectory.</span></div>
                </div>
                <div class="code-block">
                  <div class="code-content">
                    <div class="code-pane active">
                      <pre><span class="fn">$</span> <span class="str">commerceforge theme init</span></pre>
                    </div>
                    <button class="copy-btn" onclick="copyCode(this,'commerceforge theme init')">Copy</button>
                  </div>
                </div>
              </div>
            </div>
          </div>
          <div class="acc-item" data-type="headless">
            <button class="acc-trigger" onclick="toggleAcc(this)">
              <span>Headless storefronts</span>
              <span class="acc-chevron">▼</span>
            </button>
            <div class="acc-body">
              <div class="acc-content">
                <div class="steps">
                  <div class="step"><div class="step-num">1</div><span>Install CommerceForge CLI globally.</span></div>
                  <div class="step"><div class="step-num">2</div><span>Navigate to the directory where you want to create your Hydrogen storefront.</span></div>
                  <div class="step"><div class="step-num">3</div><span>Run the second command to initialize a Hydrogen storefront in a new subdirectory.</span></div>
                </div>
                <div class="code-block">
                  <div class="code-content">
                    <div class="code-pane active">
                      <pre><span class="fn">$</span> <span class="str">commerceforge hydrogen init</span></pre>
                    </div>
                    <button class="copy-btn" onclick="copyCode(this,'commerceforge hydrogen init')">Copy</button>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
      <div class="cli-right">
        <div class="section-label">Install</div>
        <h3 style="font-size:1.1rem;font-weight:600;margin-bottom:1rem;">Install the CLI</h3>
        <div class="code-block">
          <div class="code-tabs">
            <button class="code-tab active" onclick="switchTab(this,'npm')">npm</button>
            <button class="code-tab" onclick="switchTab(this,'yarn')">yarn</button>
            <button class="code-tab" onclick="switchTab(this,'pnpm')">pnpm</button>
          </div>
          <div class="code-content">
            <div class="code-pane active" id="tab-npm">
              <pre><span class="fn">$</span> <span class="kw">npm</span> i -g <span class="str">@commerceforge/cli@latest</span></pre>
            </div>
            <div class="code-pane" id="tab-yarn">
              <pre><span class="fn">$</span> <span class="kw">yarn</span> global add <span class="str">@commerceforge/cli@latest</span></pre>
            </div>
            <div class="code-pane" id="tab-pnpm">
              <pre><span class="fn">$</span> <span class="kw">pnpm</span> add -g <span class="str">@commerceforge/cli@latest</span></pre>
            </div>
            <button class="copy-btn" id="install-copy" onclick="copyInstall()">Copy</button>
          </div>
        </div>
        <p style="font-size:0.82rem;color:var(--muted);margin-top:1rem;line-height:1.6;">Requires Node.js 18+. The CLI will scaffold everything including authentication, API clients, and starter templates.</p>
        <div style="margin-top:1.5rem;padding:1rem 1.25rem;background:rgba(0,212,170,0.06);border:1px solid rgba(0,212,170,0.2);border-radius:10px">
          <p style="font-size:0.8rem;color:var(--muted);margin-bottom:0.35rem;font-weight:500;color:var(--accent)">💡 Pro tip</p>
          <p style="font-size:0.82rem;color:var(--muted);line-height:1.6">Install once and manage all your CommerceForge projects — apps, themes, and storefronts — from a single CLI tool.</p>
        </div>
      </div>
    </div>
  </div>
</section>

<!-- LAUNCH CTA -->
<section>
  <div class="section-inner">
