  btn.textContent = 'Copied!';
  setTimeout(()=>btn.textContent='Copy',1800);
}
function copyCode(btn, text){
  navigator.clipboard.writeText(text);
  btn.textContent = 'Copied!';
  setTimeout(()=>btn.textContent='Copy',1800);
}
